320	     *
321	     * @param name to test
322	     * @return true if pet name is already in use
323	     */
324	    public Pet getPet(String name, boolean ignoreNew) {
325	        name = name.toLowerCase();
326	        for (Pet pet : getPetsInternal()) {
327	            if (!ignoreNew || !pet.isNew()) {
328	                String compName = pet.getName();
329	                compName = compName.toLowerCase();
330	                if (compName.equals(name)) {
331	                    return pet;
332	                }
333	            }
334	        }
335	        return null;
336	    }
337	
338	    public Pet getPet(Integer petId) {
339	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
340	    }
341	
342	    @Override
